SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, MONTH(signup_date) AS signup_month, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count, MIN(credit_limit) AS min_credit_limit FROM customers WHERE (country NOT IN ('JP', 'DE', 'US') AND MONTH(signup_date) IN (5, 9, 12)) OR is_active GROUP BY signup_cohort, signup_month HAVING COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) > 3;
